func _init():
	var boundary = PackedVector2Array([Vector2(0, 0), Vector2(100, 0), Vector2(100, 100), Vector2(0, 100)])
	var hole1 = PackedVector2Array([Vector2(10, 10), Vector2(40, 10), Vector2(40, 40), Vector2(10, 40)])
	var hole2 = PackedVector2Array([Vector2(60, 60), Vector2(90, 60), Vector2(90, 90), Vector2(60, 90)])

	var holes = [hole1, hole2]

	# Collect all x coordinates
	var x_coords = []
	for p in boundary:
		x_coords.append(p.x)
	for hole in holes:
		for p in hole:
			x_coords.append(p.x)

	x_coords.sort()

	# Remove duplicates with tolerance
	var unique_x = []
	for x in x_coords:
		if unique_x.size() == 0 or abs(x - unique_x[-1]) > 0.0001:
			unique_x.append(x)

	print("Unique X coordinates: ", unique_x)

	# Find Y bounds
	var y_min = boundary[0].y
	var y_max = boundary[0].y
	for p in boundary:
		y_min = min(y_min, p.y)
		y_max = max(y_max, p.y)
	for hole in holes:
		for p in hole:
			y_min = min(y_min, p.y)
			y_max = max(y_max, p.y)

	y_min -= 10.0
	y_max += 10.0

	var all_triangles = []

	for i in range(unique_x.size() - 1):
		var x1 = unique_x[i]
		var x2 = unique_x[i+1]
		var strip = PackedVector2Array([
			Vector2(x1, y_min),
			Vector2(x2, y_min),
			Vector2(x2, y_max),
			Vector2(x1, y_max)
		])

		var strip_boundary = Geometry2D.intersect_polygons(boundary, strip)
		var strip_walkable = strip_boundary

		for hole in holes:
			var strip_hole = Geometry2D.intersect_polygons(hole, strip)
			for sh in strip_hole:
				var next_strip_walkable = []
				for sw in strip_walkable:
					var clipped = Geometry2D.clip_polygons(sw, sh)
					next_strip_walkable.append_array(clipped)
				strip_walkable = next_strip_walkable

		print("Strip [", x1, ", ", x2, "] has ", strip_walkable.size(), " walkable polygons.")
		for sw in strip_walkable:
			var tris = Geometry2D.triangulate_polygon(sw)
			print("  Polygon size: ", sw.size(), " Triangles indices count: ", tris.size())
			if tris.size() > 0:
				for t in range(0, tris.size(), 3):
					var p1 = sw[tris[t]]
					var p2 = sw[tris[t+1]]
					var p3 = sw[tris[t+2]]
					all_triangles.append([p1, p2, p3])

	print("Total triangles generated: ", all_triangles.size())
	quit()

