func _init():
	var T = 500
	var triangles = []
	for i in range(T):
		var p1 = Vector2(randf() * 1000, randf() * 1000)
		var p2 = p1 + Vector2(randf() * 10, randf() * 10)
		var p3 = p1 + Vector2(randf() * 10, randf() * 10)
		triangles.append([p1, p2, p3])

	var start_time = Time.get_ticks_msec()

	var unique_vertices = []
	var triangle_vertex_indices = []
	var spatial_hash = {}
	var cell_size = 1.0

	for t in range(T):
		var indices = []
		for p in triangles[t]:
			var cx = int(floor(p.x / cell_size))
			var cy = int(floor(p.y / cell_size))
			var found_idx = -1

			# Check cell and 8 neighbors
			for dx in [-1, 0, 1]:
				for dy in [-1, 0, 1]:
					var cell = Vector2i(cx + dx, cy + dy)
					if spatial_hash.has(cell):
						for idx in spatial_hash[cell]:
							if p.distance_to(unique_vertices[idx]) < 0.0001:
								found_idx = idx
								break
					if found_idx != -1:
						break
				if found_idx != -1:
					break

			if found_idx == -1:
				found_idx = unique_vertices.size()
				unique_vertices.append(p)
				var cell = Vector2i(cx, cy)
				if not spatial_hash.has(cell):
					spatial_hash[cell] = []
				spatial_hash[cell].append(found_idx)

			indices.append(found_idx)
		triangle_vertex_indices.append(indices)

	var adjacency = []
	for i in range(T):
		adjacency.append([])

	# Let's also optimize adjacency computation!
	# Two triangles are adjacent if they share an edge.
	# An edge can be represented as a pair of unique vertex indices (u, v) with u < v.
	# We can use a dictionary mapping edge -> list of triangle indices.
	var edge_to_triangles = {}
	for i in range(T):
		var indices = triangle_vertex_indices[i]
		var edges = [
			Vector2i(min(indices[0], indices[1]), max(indices[0], indices[1])),
			Vector2i(min(indices[1], indices[2]), max(indices[1], indices[2])),
			Vector2i(min(indices[2], indices[0]), max(indices[2], indices[0]))
		]
		for edge in edges:
			if not edge_to_triangles.has(edge):
				edge_to_triangles[edge] = []
			edge_to_triangles[edge].append(i)

	for edge in edge_to_triangles:
		var tris = edge_to_triangles[edge]
		if tris.size() == 2:
			var t1 = tris[0]
			var t2 = tris[1]
			adjacency[t1].append(t2)
			adjacency[t2].append(t1)

	for i in range(T):
		adjacency[i].sort()

	var end_time = Time.get_ticks_msec()
	print("Optimized time taken for T = ", T, ": ", end_time - start_time, " ms")
	print("Unique vertices: ", unique_vertices.size())
	quit()

